    _profObs=new IntersectionObserver(ents=>{ for(const en of ents){ if(en.isIntersecting){ const pk=en.target.dataset.pk; _profObs.unobserve(en.target); if(pk) needProfile(pk); } } }, { rootMargin:'600px 0px' });
