  async function renderAiFiles(pane){
    let files=[], orphans=[], orphanBytes=0, err='';
    await ensureFileAuth();          // the thumbnails below hit /client/file — cookie must exist first
    try{ const auth=await sign(27235,'ai-files',[['p',ME.pubkey]]);
      const r=await fetch('/client/ai-files',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({pubkey:ME.pubkey,auth:btoa(JSON.stringify(auth))})}).then(r=>r.json());
      if(r && r.ok===false) err=r.error||'request failed';
      files=(r&&r.files)||[]; orphans=(r&&r.orphans)||[]; orphanBytes=(r&&r.orphan_bytes)||0; }catch(e){ err=e.message||'sign/fetch failed'; }
    // Unreferenced artifacts: blobs whose chat is gone, so nothing can show or open them. They still
    // occupy storage (this pile reached GBs unnoticed), so report the size and offer one clean-up.
    const orphanBar = orphans.length
      ? `<div class="files-orphans">🧹 <b>${orphans.length}</b> unreferenced artifact${orphans.length===1?'':'s'} · ${_fmtBytes(orphanBytes)}
           <span class="muted small">left over from deleted chats — nothing can open them</span>
           <button class="btn btn-red small" id="orphan-prune">Clean up</button></div>` : '';
    // Always show the section so it's discoverable. Surface errors/empty rather than vanishing.
    if(!files.length){
      pane.innerHTML=orphanBar+`<div class="empty" style="margin:16px">${err?('Couldn\'t load: '+enc(err)):'No AI chat files yet — upload a file or generate an image in PosterChan AI.'}</div>`;
      _wireOrphanPrune(pane);
      return;
    }
    pane.innerHTML=orphanBar+`<div class="files-grid">${files.map(f=>{
        const isImg=/^image\//.test(f.mime)||f.kind==='generated';
        // /client/ai-files returns ROOT-RELATIVE urls, so they must go through _absUrl: in the bundled
        // app the page origin is https://localhost, and an <img src>/<a href> resolves against the PAGE
        // (it never sees the fetch shim) — so the raw path pointed the whole grid at localhost. _absUrl
        // is also what attaches the ?t= ownership token when the instance is cleartext (an .onion).
        const url=_absUrl(f.url);
        const thumb=isImg?`<img alt="" src="${enc(thumbUrl(url))}" loading="lazy">`:`<div class="file-icon">📎<span>${enc((f.mime.split('/')[1]||'file').slice(0,8))}</span></div>`;
        const dlName=downloadName({sha256:f.sha, type:f.mime, url}, f.name, '');
        return `<div class="file-card" data-sha="${enc(f.sha)}"><a href="${enc(url)}" data-mime="${enc(f.mime||'')}" target="_blank">${thumb}</a><button class="copy" data-url="${enc(url)}" title="Copy URL">⧉</button><button class="del" data-sha="${enc(f.sha)}" aria-label="Delete"><svg class="ic x-ic" aria-hidden="true"><use href="#i-close"></use></svg></button><div class="meta"><span class="fname" title="${enc(f.name||'')}">${enc(fileLabel(f.name, extOfBlob({url, type:f.mime}, {name:f.name}), 0))}</span><span class="fc-acts"><button class="dlbtn" data-url="${enc(url)}" data-name="${enc(dlName)}" title="Download ${enc(dlName)}"><svg class="ic b-ic" aria-hidden="true"><use href="#i-download"></use></svg></button></span></div></div>`;
      }).join('')}</div>`;
    $$('.del',pane).forEach(b=> b.onclick=()=>delAiFile(b.dataset.sha));
    $$('.copy',pane).forEach(b=> b.onclick=()=>copyUrl(b.dataset.url));
    $$('.dlbtn',pane).forEach(b=> b.onclick=e=>{ e.preventDefault(); e.stopPropagation(); downloadBlobFile(b.dataset.url, b.dataset.name); });
    _wireOrphanPrune(pane);
  }
  function _wireOrphanPrune(pane){
    const b=$('#orphan-prune',pane); if(!b) return;
    b.onclick=async()=>{
      if(!await uiConfirm('Delete every unreferenced artifact? They belong to chats that no longer exist and cannot be opened.')) return;
      b.disabled=true; b.textContent='Cleaning…';
      try{ const auth=await sign(27235,'ai-files',[['p',ME.pubkey]]);
        const r=await fetch('/client/ai-files-prune',{method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify({pubkey:ME.pubkey,auth:btoa(JSON.stringify(auth))})}).then(r=>r.json());
        if(r&&r.ok) toast(`freed ${_fmtBytes(r.bytes||0)} (${r.deleted||0} file${r.deleted===1?'':'s'})`);
        else toast((r&&r.error)||'clean-up failed');
      }catch(_){ toast('clean-up failed'); }
      renderBlossom();
    };
  }
  async function delAiFile(sha){
    if(!await uiConfirm('Delete this AI file?')) return;
    try{ const auth=await sign(27235,'ai-file-delete',[['p',ME.pubkey]]);
      const r=await fetch('/client/ai-file-delete',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({pubkey:ME.pubkey,sha,auth:btoa(JSON.stringify(auth))})}).then(r=>r.json());
      if(r&&r.ok){ toast('deleted'); renderBlossom(); } else toast((r&&r.error)||'delete failed');
    }catch(_){ toast('delete failed'); }
  }
  /* Delete one blob and forget it in the index — no confirm, no redraw. delBlob() below is the
   * single-file UI path; this is for a caller that has already confirmed and is deleting many
   * (notes.js "delete all notes and files"). 404 counts as success: the blob being already gone
   * still means the index entry should go, which is what left files stuck as "delete failed". */
  // The Blossom DELETE alone — drops THIS account's reference; the bytes go with the last owner.
  async function _blobDelete(sha){
    try{
      const auth=await sign(24242,'Delete blob',[['t','delete'],['x',sha],['expiration',String(Math.floor(Date.now()/1000)+3600)]]);
      const res=await fetch(mediaServer()+'/'+sha,{ method:'DELETE', headers:{'Authorization':'Nostr '+btoa(JSON.stringify(auth))} });
      return res.ok || res.status===404;
    }catch(_){ return false; }
  }
  async function deleteBlobQuiet(sha){
    if(!await _blobDelete(sha)) return false;
    try{ FilesIdx.forget(sha); _filesDeleted.add(sha); delete _trackUrls[sha]; }catch(_){ }
    return true;
  }
  /* Rename a file on the drive.
   *
   * THE NAME IS NOT IN THE FILE. A Blossom server keys on the sha256 and has no idea what anything is
   * called — every name you see in Files comes from the encrypted index this client owns. So a rename
   * is an index edit: nothing is re-uploaded, nothing is re-encrypted, the hash does not change, and
   * it costs the same for a 4GB video as for a text file. It also works on a blob somebody else
   * uploaded, because naming it was always ours to do.
   *
   * Asked for the MUSIC folder in particular, where generated songs land with machine-made names —
   * and the player reads its titles from the same index, so a track renamed here is renamed there.
   *
   * The verdict comes from endBatch rather than from having called setFile: the index save is what
   * can fail (a relay that will not take the write, the collapse guard refusing a shrink), and
   * reporting "renamed" on the strength of a local mutation is how a rename comes back on the next
   * load with nothing said. */
  async function renameBlob(sha, current){
    if(!sha) return;
    const cur = String(current || '');
    const asked = await uiPrompt('Rename', { value: cur, ok: 'Rename' });
    if(asked === null || asked === undefined) return;
    // Slashes would read as folders in a path and the index is flat; a name is a name.
    const name = String(asked).trim().replace(/[\/\\]+/g, '-').slice(0, 200);
    if(!name || name === cur) return;
    try{
      FilesIdx.beginBatch();
      FilesIdx.setFile(sha, { name });
      const saved = await FilesIdx.endBatch();
      if(!saved){ toast('not saved — your drive index is unchanged'); return; }
      toast('renamed');
      // Repaint through the view's own entry point, not the grid builder: a Music folder drawn by
      // _renderFilesGrid is a different screen, not a filtered one (see the note there).
      try{ if(VIEW === 'blossom') renderBlossom(); }catch(_){}
      try{ if(VIEW === 'music') renderMusicApp(); }catch(_){}
      // The desktop's Now-playing widget shows the track TITLE, which is the thing that just changed.
      try{ if(window.PCOS && PCOS.musicChanged) PCOS.musicChanged(); }catch(_){}
    }catch(e){ toast('could not rename that: ' + ((e && e.message) || '')); }
  }

  async function delBlob(sha){
    if(!await uiConfirm('Delete this blob?'))return; const server=mediaServer();
    const auth=await sign(24242,'Delete blob',[['t','delete'],['x',sha],['expiration',String(Math.floor(Date.now()/1000)+3600)]]);
    const res=await fetch(server+'/'+sha,{ method:'DELETE', headers:{'Authorization':'Nostr '+btoa(JSON.stringify(auth))} });
    // 404 = the blob is already gone from the server, but a stale entry is still in the Files index → still
    // forget it, so an already-deleted blob can be cleared from the file manager (was stuck as "delete failed").
    if(res.ok || res.status===404){
      FilesIdx.forget(sha); _filesDeleted.add(sha); delete _trackUrls[sha];
      // Drop the card NOW. renderBlossom() re-fetches the listing and redraws, but that is async and
      // races: FilesIdx.forget() kicks off an index re-upload on the same connection, and until the
      // redraw lands the deleted file is still on screen — which is what "not gone until refresh"
      // was. The bulk path never showed it because it deletes many, then redraws once at the end.
      // Removing the element is unconditional and instant; the redraw below still reconciles with
      // the server, so this can only ever be ahead of the truth, never behind it.
      try{ const card=document.querySelector('.file-card[data-sha="'+sha+'"]'); if(card) card.remove(); }catch(_){}
      _filesSel.delete(sha);
      toast(res.ok?'deleted':'removed');
      renderBlossom();
    }
    else toast('delete failed');
  }

