        if(VIEW==='notifications'){ try{ renderNotifications(); }catch(_){} }
        else { _updBadge = true; try{ bumpNotif(); }catch(_){} try{ toast('\u2b06\ufe0f App update available \u2014 see Notifications'); }catch(_){} }
